SELECT ?sectorName (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocationPct)
WHERE {
  ?sectorAllocation a ex:SectorAllocation ;
                     ex:hasInvestor ?investorProfile ;
                     ex:sectorName ?sectorName ;
                     ex:allocationPct ?allocationPct .
